  function handleEffectClick(e){const layer=F.selectedLayer();if(!layer)return;const enabled=e.target.closest('[data-effect-enabled]');if(enabled){F.edit('切换效果',()=>{const fx=layer.effects.find(f=>f.id===enabled.dataset.effectEnabled);fx.enabled=!fx.enabled});return}const del=e.target.closest('[data-effect-delete]');if(del){F.edit('删除效果',()=>layer.effects.splice(Number(del.dataset.effectDelete),1));return}const up=e.target.closest('[data-effect-up]');if(up){F.edit('调整效果顺序',()=>{const i=Number(up.dataset.effectUp);if(i>0)[layer.effects[i-1],layer.effects[i]]=[layer.effects[i],layer.effects[i-1]]})}}
